    "index": 1,
    "modal": "Must",
    "text": "judge-jev tests MUST run offline against recorded Jev answers."
  },
  "record": {
    "id": "NFR-JEV-0001",
    "title": "Deterministic offline tests",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-07",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: Jev is TypeSafe's hosted judge model: it answers each\nmultiple-choice question about a text with one choice and a confidence from\n0 to 1. A Jev request is one call to it. Recorded Jev answers are an answers\nfile (`--answers-file`): JSON answers given to judge-jev in place of a live\nJev call.",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev tests MUST run offline against recorded Jev answers."
        },
        {
          "modal": "MustNot",
          "text": "judge-jev tests MUST NOT depend on timing."
        },
        {
          "modal": "MustNot",
          "text": "judge-jev tests MUST NOT depend on sleeps."
        },
        {
          "modal": "MustNot",
          "text": "judge-jev tests MUST NOT depend on ordering."
        }
      ]
    },
    "rationale": "Flaky tests are prohibited; live Jev calls are neither free nor\nrepeatable.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "The test suite passes 20 consecutive runs with networking disabled.",
          "checked": false
        }
      ],
